      --text-primary: #121212;
      --text-secondary: #4d4d4d;
      --text-link: #777777;
      --brand: #eb0028;
      --line: #e7e9ee;
      --muted-panel: #f5f7fa;
      --focus: #0d6efd;
      --shadow: 0 16px 36px rgba(18, 18, 18, 0.14);
    }

    * { box-sizing: border-box; }

    html, body { height: 100%; }

    body {
      margin: 0;
      font-family: Inter, "DM Sans", "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
      background: var(--bg);
      color: var(--text-primary);
      -webkit-font-smoothing: antialiased;
      text-rendering: optimizeLegibility;
    }

    .page-wrap {
      min-height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 36px 20px 140px;
    }

    .content {
      width: min(100%, 720px);
      text-align: center;
    }

    .logo {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 34px;
      color: var(--brand);
      font-weight: 750;
      letter-spacing: 0.02em;
      line-height: 1;
      font-size: clamp(2rem, 7.2vw, 3.4rem);
      user-select: none;
    }

    .logo-e {
      display: inline-block;
      width: 0.86em;
      height: 0.78em;
      margin: 0 0.02em;
      border: 2px dashed currentColor;
      border-radius: 0.12em;
      transform: translateY(0.02em);
    }

    .headline {
      font-size: clamp(1.45rem, 2.3vw, 2rem);
      font-weight: 600;
      letter-spacing: -0.015em;
      margin: 0 0 12px;
    }

    .support-copy {
      margin: 0 auto 30px;
      max-width: 560px;
      color: var(--text-secondary);
      font-size: clamp(1rem, 1.8vw, 1.1rem);
      line-height: 1.55;
    }

    .search-form {
      margin: 0 auto 22px;
      width: min(100%, 560px);
    }

    .search-row {
      position: relative;
      display: flex;
      align-items: center;
    }

    .search-input {
      width: 100%;
      height: 56px;
      border: 1px solid #d5dbe5;
      border-radius: 12px;
      padding: 0 58px 0 18px;
      font-size: 1rem;
      color: var(--text-primary);
      background: #fff;
      transition: border-color 160ms ease, box-shadow 160ms ease;
    }

    .search-input::placeholder { color: #8a8f9d; }

    .search-input:focus-visible,
    .search-btn:focus-visible,
    .link:focus-visible,
    .cookie-link:focus-visible,
    .pref-btn:focus-visible,
    .modal-close:focus-visible,
    .modal-save:focus-visible,
    .toggle input:focus-visible + .toggle-ui,
    .modal-panel a:focus-visible {
      outline: 3px solid rgba(13, 110, 253, 0.28);
      outline-offset: 2px;
    }

    .search-input:focus {
      border-color: #97aac9;
      box-shadow: 0 0 0 4px rgba(13, 110, 253, 0.08);
      outline: none;
    }

    .search-btn {
      position: absolute;
      right: 8px;
      top: 8px;
      width: 40px;
      height: 40px;
      border: 0;
      border-radius: 10px;
      background: #f4f7fb;
      color: #2f3a4a;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      transition: background-color 120ms ease;
    }

    .search-btn:hover { background: #e8eef7; }

    .error-code {
      margin: 18px auto 28px;
      width: min(100%, 560px);
      background: var(--muted-panel);
      color: #6e7481;
      border-radius: 10px;
      padding: 12px 16px;
      font-size: 0.96rem;
      font-weight: 500;
    }

    .divider {
      margin: 0 auto 30px;
      width: min(100%, 560px);
      border: 0;
      border-top: 1px solid var(--line);
    }

    .next-title {
      margin: 0 0 14px;
      font-size: 1rem;
      font-weight: 600;
      color: #2f2f2f;
    }

    .link-list {
      display: flex;
      gap: 16px;
      justify-content: center;
      flex-wrap: wrap;
      margin: 0;
      padding: 0;
      list-style: none;
    }

    .link {
      color: var(--text-link);
      text-decoration-thickness: 1.4px;
      text-underline-offset: 2.2px;
      font-weight: 500;
    }

    .link:hover { color: #4a4f57; }

    .cookie-banner {
      position: fixed;
      left: 0;
      right: 0;
      bottom: 0;
      z-index: 30;
      border-top: 1px solid #dce2eb;
      background: rgba(255, 255, 255, 0.97);
      backdrop-filter: blur(3px);
    }

    .cookie-inner {
      width: min(100%, 1120px);
      margin: 0 auto;
      padding: 16px 18px;
      display: flex;
      align-items: center;
      gap: 14px 18px;
      justify-content: space-between;
      flex-wrap: wrap;
    }

    .cookie-text {
      margin: 0;
      color: #585f6d;
      font-size: 0.92rem;
      line-height: 1.45;
      max-width: 860px;
    }

    .cookie-link { color: #596476; }

    .pref-btn {
      border: 1px solid #cfd8e5;
      background: #fff;
      color: #2f3a4a;
      border-radius: 10px;
      height: 42px;
      padding: 0 16px;
      font-size: 0.92rem;
      font-weight: 600;
      cursor: pointer;
      white-space: nowrap;
    }

    .pref-btn:hover { background: #f7f9fc; }

    .modal-backdrop {
      position: fixed;
      inset: 0;
      background: rgba(12, 18, 28, 0.42);
      display: none;
      align-items: center;
      justify-content: center;
      padding: 20px;
      z-index: 40;
    }

    .modal-backdrop[aria-hidden="false"] { display: flex; }

    .modal-panel {
      width: min(100%, 520px);
      background: #fff;
      border-radius: 14px;
      box-shadow: var(--shadow);
      padding: 18px 18px 16px;
    }

    .modal-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 8px;
    }

    .modal-title {
      margin: 0;
      font-size: 1.05rem;
      font-weight: 650;
    }

    .modal-close {
      width: 34px;
      height: 34px;
      border: 0;
      border-radius: 9px;
      background: #f2f5f9;
      cursor: pointer;
      font-size: 1.2rem;
      line-height: 1;
    }

    .modal-copy {
      margin: 0 0 14px;
      color: #545d6c;
      font-size: 0.93rem;
      line-height: 1.5;
    }

    .pref-list {
      margin: 0;
      padding: 0;
      list-style: none;
      display: grid;
      gap: 10px;
    }

    .pref-item {
      border: 1px solid #e5e9f0;
      border-radius: 12px;
      padding: 10px 12px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
    }

    .pref-label {
      margin: 0;
      font-size: 0.93rem;
      color: #2f3540;
    }

    .toggle {
      position: relative;
      display: inline-flex;
      align-items: center;
    }

    .toggle input {
      position: absolute;
      opacity: 0;
      width: 0;
      height: 0;
    }

    .toggle-ui {
      width: 44px;
      height: 26px;
      border-radius: 999px;
      background: #cad2dd;
      position: relative;
      transition: background 140ms ease;
      cursor: pointer;
    }

    .toggle-ui::after {
      content: "";
      position: absolute;
      width: 20px;
      height: 20px;
      border-radius: 50%;
      background: white;
      left: 3px;
      top: 3px;
      transition: transform 140ms ease;
    }

    .toggle input:checked + .toggle-ui {
      background: #5f768f;
    }

    .toggle input:checked + .toggle-ui::after {
      transform: translateX(18px);
    }

    .modal-actions {
      display: flex;
      justify-content: flex-end;
      gap: 10px;
      margin-top: 14px;
    }

    .modal-save {
      border: 1px solid #cfd8e5;
      background: #fff;
      color: #253041;
      border-radius: 9px;
      height: 38px;
      padding: 0 14px;
      font-size: 0.9rem;
      font-weight: 600;
      cursor: pointer;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    @media (max-width: 768px) {
      .page-wrap { padding: 30px 16px 168px; align-items: flex-start; }
      .content { margin-top: 3vh; }
      .logo { margin-bottom: 28px; }
      .headline { margin-bottom: 10px; }
      .support-copy { margin-bottom: 24px; }
      .search-input { height: 54px; border-radius: 11px; }
      .error-code { margin-bottom: 24px; }
      .divider { margin-bottom: 24px; }
      .cookie-inner { align-items: flex-start; }
    }

    @media (max-width: 480px) {
      .page-wrap { padding-bottom: 186px; }
      .link-list { flex-direction: column; gap: 10px; }
      .cookie-inner { padding: 14px 14px; }
      .pref-btn { width: 100%; }
      .modal-panel { padding: 16px; }
    }
  </style>
</head>
<body>
  <main class="page-wrap" id="main-content">
    <div class="content">
      <div class="logo" aria-label="IdeaForum">
        ID<span class="logo-e" aria-hidden="true"></span>AFORUM
      </div>

      <h1 class="headline">Sorry, we can't find that.</h1>
      <p class="support-copy">Perhaps we can help you find the content you're looking for:</p>

      <form class="search-form" id="search-form" role="search" aria-label="Search IdeaForum">
        <div class="search-row">
          <label class="sr-only" for="search-input">Search IdeaForum</label>
          <input
            id="search-input"
            class="search-input"
            name="q"
            type="search"
            placeholder="Search IdeaForum..."
            autocomplete="off"
            required
          />
          <button class="search-btn" type="submit" aria-label="Search">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <circle cx="11" cy="11" r="7" stroke="currentColor" stroke-width="2"></circle>
              <path d="M16.65 16.65L21 21" stroke="currentColor" stroke-width="2" stroke-linecap="round"></path>
            </svg>
          </button>
        </div>
      </form>

      <div class="error-code" aria-label="HTTP error">HTTP Error 404</div>
      <hr class="divider" />

      <h2 class="next-title">What's next?</h2>
      <ul class="link-list">
        <li><a class="link" href="/" aria-label="Go to the homepage">Go to the homepage</a></li>
        <li><a class="link" href="/help" aria-label="Visit our Help Desk">Visit our Help Desk</a></li>
      </ul>
    </div>
  </main>

  <aside class="cookie-banner" id="cookie-banner" aria-label="Cookie consent banner">
    <div class="cookie-inner">
      <p class="cookie-text">
        This website utilizes technologies such as cookies to enable essential site functionality, as well as for analytics,
        personalization, and targeted advertising. To learn more, view the following link:
        <a class="cookie-link" href="https://example.com/privacy" target="_blank" rel="noopener noreferrer">Privacy Policy</a>
      </p>
      <button class="pref-btn" id="manage-preferences" type="button">Manage Preferences</button>
    </div>
  </aside>

  <div class="modal-backdrop" id="pref-modal" aria-hidden="true">
    <section class="modal-panel" role="dialog" aria-modal="true" aria-labelledby="pref-title">
      <div class="modal-header">
        <h3 class="modal-title" id="pref-title">Cookie Preferences</h3>
        <button class="modal-close" id="modal-close" type="button" aria-label="Close preferences">×</button>
      </div>
      <p class="modal-copy">Configure how IdeaForum uses cookies and similar technologies. Essential cookies are always enabled.</p>

      <ul class="pref-list">
        <li class="pref-item">
          <p class="pref-label">Essential cookies</p>
          <label class="toggle" aria-label="Essential cookies enabled">
            <input type="checkbox" checked disabled />
            <span class="toggle-ui" aria-hidden="true"></span>
          </label>
        </li>
        <li class="pref-item">
          <p class="pref-label">Analytics</p>
          <label class="toggle" aria-label="Analytics cookies">
            <input id="analytics-toggle" type="checkbox" />
            <span class="toggle-ui" aria-hidden="true"></span>
          </label>
        </li>
        <li class="pref-item">
          <p class="pref-label">Personalization</p>
          <label class="toggle" aria-label="Personalization cookies">
            <input id="personalization-toggle" type="checkbox" />
            <span class="toggle-ui" aria-hidden="true"></span>
          </label>
        </li>
        <li class="pref-item">
          <p class="pref-label">Targeted advertising</p>
          <label class="toggle" aria-label="Advertising cookies">
            <input id="ads-toggle" type="checkbox" />
            <span class="toggle-ui" aria-hidden="true"></span>
          </label>
        </li>
      </ul>

      <div class="modal-actions">
        <button class="modal-save" id="save-preferences" type="button">Save Preferences</button>
      </div>
    </section>
  </div>

  <script>
    const searchForm = document.getElementById('search-form');
    const searchInput = document.getElementById('search-input');
    const prefTrigger = document.getElementById('manage-preferences');
    const prefModal = document.getElementById('pref-modal');
    const closeBtn = document.getElementById('modal-close');
    const saveBtn = document.getElementById('save-preferences');

    function openModal() {
      prefModal.setAttribute('aria-hidden', 'false');
      closeBtn.focus();
      document.body.style.overflow = 'hidden';
    }

    function closeModal() {
      prefModal.setAttribute('aria-hidden', 'true');
      document.body.style.overflow = '';
      prefTrigger.focus();
    }

    prefTrigger.addEventListener('click', openModal);
    closeBtn.addEventListener('click', closeModal);

    prefModal.addEventListener('click', (event) => {
      if (event.target === prefModal) closeModal();
    });

    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape' && prefModal.getAttribute('aria-hidden') === 'false') {
        closeModal();
      }
    });

    saveBtn.addEventListener('click', closeModal);

    searchForm.addEventListener('submit', (event) => {
      event.preventDefault();
      const query = searchInput.value.trim();
      if (!query) return;
      const searchUrl = `./search.html?q=${encodeURIComponent(query)}`;
      window.location.href = searchUrl;
    });
  </script>
</body>
</html>
EOF

