      content: "";
      position: absolute;
      width: 20px;
      height: 20px;
      border-radius: 50%;
      background: white;
      left: 3px;
      top: 3px;
      transition: transform 140ms ease;
    }

    .toggle input:checked + .toggle-ui {
      background: #5f768f;
    }

    .toggle input:checked + .toggle-ui::after {
      transform: translateX(18px);
    }

    .modal-actions {
      display: flex;
      justify-content: flex-end;
      gap: 10px;
      margin-top: 14px;
    }

    .modal-save {
      border: 1px solid #cfd8e5;
      background: #fff;
      color: #253041;
      border-radius: 9px;
      height: 38px;
      padding: 0 14px;
      font-size: 0.9rem;
      font-weight: 600;
      cursor: pointer;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    @media (max-width: 768px) {
      .page-wrap { padding: 30px 16px 168px; align-items: flex-start; }
      .content { margin-top: 3vh; }
      .logo { margin-bottom: 28px; }
      .headline { margin-bottom: 10px; }
      .support-copy { margin-bottom: 24px; }
      .search-input { height: 54px; border-radius: 11px; }
      .error-code { margin-bottom: 24px; }
      .divider { margin-bottom: 24px; }
      .cookie-inner { align-items: flex-start; }
    }

    @media (max-width: 480px) {
      .page-wrap { padding-bottom: 186px; }
      .link-list { flex-direction: column; gap: 10px; }
      .cookie-inner { padding: 14px 14px; }
      .pref-btn { width: 100%; }
      .modal-panel { padding: 16px; }
    }
  </style>
</head>
<body>
  <main class="page-wrap" id="main-content">
    <div class="content">
      <div class="logo" aria-label="IdeaForum">
        ID<span class="logo-e" aria-hidden="true"></span>AFORUM
      </div>

      <h1 class="headline">Sorry, we can't find that.</h1>
      <p class="support-copy">Perhaps we can help you find the content you're looking for:</p>

      <form class="search-form" id="search-form" role="search" aria-label="Search IdeaForum">
        <div class="search-row">
          <label class="sr-only" for="search-input">Search IdeaForum</label>
          <input
            id="search-input"
            class="search-input"
            name="q"
            type="search"
            placeholder="Search IdeaForum..."
            autocomplete="off"
            required
          />
          <button class="search-btn" type="submit" aria-label="Search">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <circle cx="11" cy="11" r="7" stroke="currentColor" stroke-width="2"></circle>
              <path d="M16.65 16.65L21 21" stroke="currentColor" stroke-width="2" stroke-linecap="round"></path>
            </svg>
          </button>
        </div>
      </form>

      <div class="error-code" aria-label="HTTP error">HTTP Error 404</div>
      <hr class="divider" />

      <h2 class="next-title">What's next?</h2>
      <ul class="link-list">
        <li><a class="link" href="/" aria-label="Go to the homepage">Go to the homepage</a></li>
        <li><a class="link" href="/help" aria-label="Visit our Help Desk">Visit our Help Desk</a></li>
      </ul>
    </div>
  </main>

  <aside class="cookie-banner" id="cookie-banner" aria-label="Cookie consent banner">
    <div class="cookie-inner">
      <p class="cookie-text">
        This website utilizes technologies such as cookies to enable essential site functionality, as well as for analytics,
        personalization, and targeted advertising. To learn more, view the following link:
        <a class="cookie-link" href="https://example.com/privacy" target="_blank" rel="noopener noreferrer">Privacy Policy</a>
      </p>
      <button class="pref-btn" id="manage-preferences" type="button">Manage Preferences</button>
    </div>
  </aside>

  <div class="modal-backdrop" id="pref-modal" aria-hidden="true">
    <section class="modal-panel" role="dialog" aria-modal="true" aria-labelledby="pref-title">
      <div class="modal-header">
        <h3 class="modal-title" id="pref-title">Cookie Preferences</h3>
        <button class="modal-close" id="modal-close" type="button" aria-label="Close preferences">×</button>
      </div>
