      <ul class="pref-list">
        <li class="pref-item">
          <p class="pref-label">Essential cookies</p>
          <label class="toggle" aria-label="Essential cookies enabled">
            <input type="checkbox" checked disabled />
            <span class="toggle-ui" aria-hidden="true"></span>
          </label>
        </li>
        <li class="pref-item">
          <p class="pref-label">Analytics</p>
          <label class="toggle" aria-label="Analytics cookies">
            <input id="analytics-toggle" type="checkbox" />
            <span class="toggle-ui" aria-hidden="true"></span>
          </label>
        </li>
        <li class="pref-item">
          <p class="pref-label">Personalization</p>
          <label class="toggle" aria-label="Personalization cookies">
            <input id="personalization-toggle" type="checkbox" />
            <span class="toggle-ui" aria-hidden="true"></span>
          </label>
        </li>
        <li class="pref-item">
          <p class="pref-label">Targeted advertising</p>
          <label class="toggle" aria-label="Advertising cookies">
            <input id="ads-toggle" type="checkbox" />
            <span class="toggle-ui" aria-hidden="true"></span>
          </label>
        </li>
      </ul>

      <div class="modal-actions">
        <button class="modal-save" id="save-preferences" type="button">Save Preferences</button>
      </div>
    </section>
  </div>

  <script>
    const searchForm = document.getElementById('search-form');
    const searchInput = document.getElementById('search-input');
    const prefTrigger = document.getElementById('manage-preferences');
    const prefModal = document.getElementById('pref-modal');
    const closeBtn = document.getElementById('modal-close');
    const saveBtn = document.getElementById('save-preferences');

    function openModal() {
      prefModal.setAttribute('aria-hidden', 'false');
      closeBtn.focus();
      document.body.style.overflow = 'hidden';
    }

    function closeModal() {
      prefModal.setAttribute('aria-hidden', 'true');
      document.body.style.overflow = '';
      prefTrigger.focus();
    }

    prefTrigger.addEventListener('click', openModal);
    closeBtn.addEventListener('click', closeModal);

    prefModal.addEventListener('click', (event) => {
      if (event.target === prefModal) closeModal();
    });

    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape' && prefModal.getAttribute('aria-hidden') === 'false') {
        closeModal();
      }
    });

    saveBtn.addEventListener('click', closeModal);

    searchForm.addEventListener('submit', (event) => {
      event.preventDefault();
      const query = searchInput.value.trim();
      if (!query) return;
      const searchUrl = `./search.html?q=${encodeURIComponent(query)}`;
      window.location.href = searchUrl;
    });
  </script>
